-- ----------------------------
-- Table structure for biz_customer
-- ----------------------------
DROP TABLE IF EXISTS `biz_customer`;
CREATE TABLE `biz_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '客户主键ID',
  `customer_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `customer_password` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户登录密码（BCrypt加密）',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号码',
  `email` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱，多个用英文逗号分隔',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态',
  `role_id` bigint NOT NULL COMMENT '角色ID（关联sys_role）',
  `salesman_id` bigint NOT NULL COMMENT '业务员ID（关联sys_user）',
  `is_sign_contract` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否签合同：0否 1是',
  `contract_file_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '合同文件ID集合',
  `account_file_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '开户文件ID集合',
  `bond_id` bigint NULL DEFAULT NULL COMMENT 'BOND_ID',
  `bond_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'BOND编号',
  `bond_status` tinyint NULL DEFAULT 1 COMMENT '绑定状态: 1-生效, 0-解绑',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建人ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新人ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '删除标志 0正常 2删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_customer_name`(`customer_name` ASC) USING BTREE,
  INDEX `idx_salesman_id`(`salesman_id` ASC) USING BTREE,
  INDEX `idx_role_id`(`role_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户信息表' ROW_FORMAT = Dynamic;

