INSERT INTO `sys_oper_log` VALUES (104, '创建表', 0, 'com.ruoyi.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"tplWebType\":\"element-plus\",\"sql\":\"CREATE TABLE cle_shipment (\\n  shipment_id BIGINT AUTO_INCREMENT COMMENT \'主键ID\',\\n  customer_id BIGINT NOT NULL COMMENT \'客户ID\',\\n  bl_no VARCHAR(100) COMMENT \'提单号\',\\n  container_no VARCHAR(100) COMMENT \'柜号\',\\n  container_type VARCHAR(50) COMMENT \'柜型\',\\n  piece_qty INT DEFAULT 0 COMMENT \'件数\',\\n  weight DECIMAL(10,2) DEFAULT 0 COMMENT \'重量KG\',\\n  volume DECIMAL(10,2) DEFAULT 0 COMMENT \'方数CBM\',\\n  carrier_code VARCHAR(50) COMMENT \'船司编码\',\\n  transport_type VARCHAR(20) COMMENT \'运输方式：海运/空运\',\\n  price_type VARCHAR(20) COMMENT \'计价方式：一口价/实报实销\',\\n  business_type VARCHAR(20) COMMENT \'业务类型：电商柜/传统整柜/特殊渠道\',\\n  load_port VARCHAR(100) COMMENT \'起运港\',\\n  transit_port VARCHAR(100) COMMENT \'中转港\',\\n  dest_port VARCHAR(100) COMMENT \'目的港\',\\n  etd DATE COMMENT \'ETD 预计离港\',\\n  eta DATE COMMENT \'ETA 预计到港\',\\n  give_container_date DATE COMMENT \'给柜日期\',\\n  isf_match_status VARCHAR(20) COMMENT \'ISF匹配状态\',\\n  customs_status VARCHAR(20) COMMENT \'清关状态\',\\n  is_confirm_customs CHAR(1) DEFAULT \'0\' COMMENT \'是否确认清关 0否1是\',\\n  remark VARCHAR(500) COMMENT \'客户备注\',\\n  create_by VARCHAR(64) DEFAULT \'\' COMMENT \'创建人\',\\n  create_time DATETIME COMMENT \'创建时间\',\\n  update_by VARCHAR(64) DEFAULT \'\' COMMENT \'更新人\',\\n  update_time DATETIME COMMENT \'更新时间\',\\n  del_flag CHAR(1) DEFAULT \'0\' COMMENT \'删除标志 0正常1删除\',\\n  PRIMARY KEY (shipment_id),\\n  INDEX idx_create_by(create_by),\\n  INDEX idx_bl_no(bl_no),\\n  INDEX idx_container_no(container_no)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'清关-货柜运单主表\';\\n\\nCREATE TABLE cle_ship_attach (\\n  attach_id BIGINT AUTO_INCREMENT,\\n  shipment_id BIGINT NOT NULL COMMENT \'关联运单ID cle_shipment.shipment_id\',\\n  attach_type VARCHAR(50) NOT NULL COMMENT \'附件类型：主提单、分提单、AN文件、DO附件、ISF申报文件...\',\\n  file_name VARCHAR(255) COMMENT \'原始文件名\',\\n  file_path VARCHAR(500) COMMENT \'存储路径\',\\n  file_size BIGINT COMMENT \'文件大小\',\\n  create_by VARCHAR(64) DEFAULT \'\',\\n  create_time DATETIME,\\n  del_flag CHAR(1) DEFAULT \'0\',\\n  PRIMARY KEY (attach_id),\\n  INDEX idx_shipment_id(ship', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-28 09:30:33', 245);
