价方式（字典）\',\\n  `business_type` varchar(50) DEFAULT NULL COMMENT \'业务类型（字典）\',\\n  `input_type` varchar(50) DEFAULT NULL COMMENT \'录入方式（字典）\',\\n  `isf_match_status` varchar(50) DEFAULT NULL COMMENT \'ISF匹配状态（字典）\',\\n  `is_confirm_clear` char(1) DEFAULT NULL COMMENT \'是否确认清关 Y是 N否\',\\n  `attach_type` var', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-28 13:43:12', 176);
