INSERT INTO `sys_oper_log` VALUES (188, '创建表', 0, 'com.dehui.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"tplWebType\":\"element-plus\",\"sql\":\"DROP TABLE IF EXISTS `biz_shipment`;\\nCREATE TABLE `biz_shipment` (\\n  `id`                  BIGINT(20)    NOT NULL AUTO_INCREMENT       COMMENT \'主键ID\',\\n\\n  -- ========== 运输与客户板块 ==========\\n  `transport_mode`      TINYINT(1)    NOT NULL DEFAULT 1            COMMENT \'运输方式：1海运 2空运\',\\n  `pricing_type`        TINYINT(1)    DEFAULT NULL                  COMMENT \'计价方式：1一口价 2实报实销\',\\n  `business_type`       TINYINT(1)    DEFAULT NULL                  COMMENT \'业务类型：1电商柜 2传统整柜 3特殊渠道\',\\n  `customer_id`         BIGINT(20)    NOT NULL                      COMMENT \'客户ID（关联客户表）\',\\n  `importer_id`         BIGINT(20)    DEFAULT NULL                  COMMENT \'进口商ID（关联进口商表）\',\\n  `container_give_date` DATE          DEFAULT NULL                  COMMENT \'给柜日期\',\\n\\n  -- ========== 单证与货物板块 ==========\\n  `bill_no`             VARCHAR(64)   NOT NULL                      COMMENT \'提单号\',\\n  `container_no`        VARCHAR(32)   DEFAULT NULL                  COMMENT \'柜号\',\\n  `container_type`      VARCHAR(32)   DEFAULT NULL                  COMMENT \'柜型（20GP/40HQ等，字典）\',\\n  `package_qty`         INT(11)       NOT NULL DEFAULT 0            COMMENT \'件数\',\\n  `weight_kg`           DECIMAL(12,2) NOT NULL DEFAULT 0.00         COMMENT \'重量(KG)\',\\n  `cbm`                 DECIMAL(12,2) NOT NULL DEFAULT 0.00         COMMENT \'方数(CBM)\',\\n\\n  -- ========== 港口与航程板块 ==========\\n  `vessel_voyage`       VARCHAR(128)  DEFAULT NULL                  COMMENT \'船名航次\',\\n  `pol_code`            VARCHAR(16)   NOT NULL                      COMMENT \'起运港代码\',\\n  `etd`                 DATETIME      NOT NULL                      COMMENT \'预计离港时间ETD\',\\n  `trans_port_code`     VARCHAR(16)   DEFAULT NULL                  COMMENT \'中转港代码\',\\n  `trans_time`          DATETIME      DEFAULT NULL                  COMMENT \'中转时间\',\\n  `pod_code`            VARCHAR(16)   NOT NULL                      COMMENT \'目的港代码\',\\n  `eta`                 DATETIME      DEFAULT NULL                  COMMENT \'预计到港时间ETA\',\\n\\n ', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-29 13:56:33', 237);
