INSERT INTO `sys_oper_log` VALUES (260, '创建表', 0, 'com.dehui.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"tplWebType\":\"element-plus\",\"sql\":\"DROP TABLE IF EXISTS `biz_port`;\\nCREATE TABLE `biz_port` (\\n  `id`                BIGINT(20)    NOT NULL AUTO_INCREMENT       COMMENT \'主键ID\',\\n  `port_name`         VARCHAR(128)  NOT NULL                      COMMENT \'港头名称\',\\n  `port_type`         VARCHAR(32)   NOT NULL                      COMMENT \'港口类型（字典port_type）\',\\n  `route_type`        VARCHAR(32)   NOT NULL                      COMMENT \'航线名称（字典route_type）\',\\n  `clear_customs_flag`VARCHAR(32)   NOT NULL                      COMMENT \'是否清关（字典clear_customs_flag）\',\\n  `load_port_code`    VARCHAR(16)   DEFAULT NULL                  COMMENT \'装货港代码\',\\n  `unload_port_code`  VARCHAR(16)   DEFAULT NULL                  COMMENT \'卸货港代码\',\\n\\n  -- Ruoyi标准审计字段\\n  `create_dept`       BIGINT(20)    DEFAULT NULL                  COMMENT \'创建部门\',\\n  `create_by`         BIGINT(20)    DEFAULT NULL                  COMMENT \'创建人ID\',\\n  `create_time`       DATETIME      DEFAULT CURRENT_TIMESTAMP     COMMENT \'创建时间\',\\n  `update_by`         BIGINT(20)    DEFAULT NULL                  COMMENT \'更新人ID\',\\n  `update_time`       DATETIME      DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n  `del_flag`          CHAR(1)       NOT NULL DEFAULT \'0\'          COMMENT \'删除标志 0正常 2删除\',\\n\\n  PRIMARY KEY (`id`),\\n  UNIQUE KEY `uk_port_name` (`port_name`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'港口码头表\';\\n\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-29 17:51:35', 305);
