INSERT INTO `sys_oper_log` VALUES (293, '创建表', 0, 'com.dehui.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"tplWebType\":\"element-plus\",\"sql\":\"CREATE TABLE `biz_customer` (\\n  `id`                BIGINT(20)    NOT NULL AUTO_INCREMENT       COMMENT \'客户主键ID\',\\n  -- 基础信息\\n  `customer_name`     VARCHAR(128)  NOT NULL                      COMMENT \'客户名称\',\\n  `customer_password` VARCHAR(100)  NOT NULL                      COMMENT \'客户登录密码（BCrypt加密）\',\\n  `phone`             VARCHAR(20)   DEFAULT NULL                  COMMENT \'手机号码\',\\n  `email`             VARCHAR(500)  DEFAULT NULL                  COMMENT \'邮箱，多个用英文逗号分隔\',\\n  -- 账号与业务配置\\n  `role_id`           BIGINT(20)    NOT NULL                      COMMENT \'角色ID（关联sys_role）\',\\n  `salesman_id`       BIGINT(20)    NOT NULL                      COMMENT \'业务员ID（关联sys_user）\',\\n  `is_sign_contract`  TINYINT(1)    NOT NULL DEFAULT 0            COMMENT \'是否签合同：0否 1是\',\\n  -- 文件资料（存sys_file的file_id，多文件逗号隔开）\\n  `contract_file_ids` VARCHAR(500)  DEFAULT NULL                  COMMENT \'合同文件ID集合\',\\n  `account_file_ids`  VARCHAR(500)  DEFAULT NULL                  COMMENT \'开户文件ID集合\',\\n  -- 备注\\n  `remark`            VARCHAR(1000) DEFAULT NULL                  COMMENT \'备注\',\\n  -- Ruoyi标准审计字段\\n  `create_dept`       BIGINT(20)    DEFAULT NULL                  COMMENT \'创建部门\',\\n  `create_by`         BIGINT(20)    DEFAULT NULL                  COMMENT \'创建人ID\',\\n  `create_time`       DATETIME      DEFAULT CURRENT_TIMESTAMP     COMMENT \'创建时间\',\\n  `update_by`         BIGINT(20)    DEFAULT NULL                  COMMENT \'更新人ID\',\\n  `update_time`       DATETIME      DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT \'更新时间\',\\n  `del_flag`          CHAR(1)       NOT NULL DEFAULT \'0\'          COMMENT \'删除标志 0正常 2删除\',\\n\\n  PRIMARY KEY (`id`),\\n  UNIQUE KEY `uk_customer_name` (`customer_name`),\\n  KEY `idx_salesman_id` (`salesman_id`),\\n  KEY `idx_role_id` (`role_id`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT=\'客户信息表\';\\n\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-30 11:41:10', 215);
