INSERT INTO `sys_oper_log` VALUES (341, '创建表', 0, 'com.dehui.generator.controller.GenController.createTableSave()', 'POST', 1, 'admin', '研发部门', '/tool/gen/createTable', '127.0.0.1', '内网IP', '{\"tplWebType\":\"element-plus\",\"sql\":\"CREATE TABLE `hs_us_product` (\\n  `id` bigint NOT NULL AUTO_INCREMENT COMMENT \'主键ID\',\\n  `cn_name` varchar(255) DEFAULT NULL COMMENT \'中文品名\',\\n  `en_name` varchar(255) DEFAULT NULL COMMENT \'英文品名\',\\n  `common_code` varchar(64) DEFAULT NULL COMMENT \'通用CODE\',\\n  `hs_code` varchar(32) DEFAULT NULL COMMENT \'海关编码\',\\n  `anti_dumping` varchar(64) DEFAULT NULL COMMENT \'反倾销\',\\n  `cpsc` varchar(64) DEFAULT NULL COMMENT \'CPSC\',\\n  `need_cert` char(1) DEFAULT NULL COMMENT \'是否需要认证\',\\n  `article_description` text DEFAULT NULL COMMENT \'Article Description\',\\n  `total_tax_rate` varchar(32) DEFAULT NULL COMMENT \'总税率\',\\n  `base_tax_rate` varchar(32) DEFAULT NULL COMMENT \'基础税率\',\\n  `section301_code` varchar(64) DEFAULT NULL COMMENT \'301加征税CODE\',\\n  `section301_tax` varchar(32) DEFAULT NULL COMMENT \'301加征税\',\\n  `fl301_232_code` varchar(64) DEFAULT NULL COMMENT \'FL301/232附加税CODE\',\\n  `fl301_232_tax` varchar(32) DEFAULT NULL COMMENT \'FL301/232附加税\',\\n  `cents_per_kg` varchar(32) DEFAULT NULL COMMENT \'Cents/kg\',\\n  `pga1` varchar(64) DEFAULT NULL COMMENT \'PGA 1\',\\n  `pga2` varchar(64) DEFAULT NULL COMMENT \'PGA 2\',\\n  `pga3` varchar(64) DEFAULT NULL COMMENT \'PGA 3\',\\n  `pga4` varchar(64) DEFAULT NULL COMMENT \'PGA 4\',\\n  `pga5` varchar(64) DEFAULT NULL COMMENT \'PGA 5\',\\n  `pga6` varchar(64) DEFAULT NULL COMMENT \'PGA 6\',\\n  `del_flag` char(1) DEFAULT \'0\' COMMENT \'删除标志\',\\n  `create_by` varchar(64) DEFAULT \'\' COMMENT \'创建者\',\\n  `create_time` datetime DEFAULT NULL COMMENT \'创建时间\',\\n  `update_by` varchar(64) DEFAULT \'\' COMMENT \'更新者\',\\n  `update_time` datetime DEFAULT NULL COMMENT \'更新时间\',\\n  `remark` varchar(500) DEFAULT NULL COMMENT \'备注\',\\n  PRIMARY KEY (`id`),\\n  KEY `idx_hs_code` (`hs_code`),\\n  KEY `idx_cn_name` (`cn_name`)\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT=\'HS查询\';\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2026-10-30 15:10:33', 204);
